private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_clipsync_mobile_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipsyncclient_create_room() != 60930) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipsyncclient_join_room() != 21047) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipsyncclient_start_sync() != 10648) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipsyncclient_status() != 45055) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_constructor_clipsyncclient_new() != 38362) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipboardbridge_read_text() != 57325) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipboardbridge_write_text() != 51528) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipboardbridge_read_image_png() != 11237) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipboardbridge_write_image_png() != 36286) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipsync_mobile_checksum_method_clipboardbridge_notify() != 13108) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitClipboardBridge()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureClipsyncMobileInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

